   "id": "z008100b1",
   "sez": "sport",
   "titolo": "Ciclismo su pista, Iúri Leitão campione del mondo nell'Omnium",
   "orig": "15h - Iuri Leitão é campeão mundial de ciclismo de pista na prova Omnium",
   "lead": "Il portoghese Iúri Leitão ha conquistato il titolo mondiale di ciclismo su pista nella prova dell'Omnium. Lo hanno annunciato la televisione pubblica RTP e il quotidiano Público. Dopo una gara definita di nervi, il corridore è tornato in cima alla specialità, confermando una lunga serie di successi: Público ricorda l'oro mondiale già conquistato in passato e il titolo europeo, a cui si aggiunge ora un nuovo campionato del mondo. Il risultato conferma Leitão come uno dei protagonisti assoluti del ciclismo su pista internazionale.",
   "more": [
    "L'Omnium è una prova multipla del ciclismo su pista che riunisce più gare in una sola giornata: scratch, tempo race, eliminazione e corsa a punti. Vince chi accumula più punti. Leitão è uno dei ciclisti portoghesi più vincenti nella disciplina, protagonista anche ai Giochi olimpici di Parigi 2024."
   ],
