   "sez": "musica",
   "titolo": "Hostia Pedagógica, l'esordio «Homo Lamentáblis»",
   "orig": "Hostia Pedagógica - Homo Lamentáblis",
   "lead": "OndaRock recensisce «Homo Lamentáblis», il primo album degli Hostia Pedagógica, un trio della Catalogna. Il disco propone un post-punk diretto e graffiante. La rivista lo descrive come una serie di «schiaffoni educativi», con un'ironia che richiama il nome stesso della band. L'esordio presenta il gruppo con una formula energica e provocatoria. Lo riferisce OndaRock.",
