   "id": "zdb931fb4",
   "sez": "musica",
   "titolo": "Newdress tornano con «ADE (A Dance Eternal)»",
   "orig": "Newdress - ADE (A Dance Eternal)",
   "lead": "I Newdress, una delle formazioni protagoniste della scena darkwave italiana, tornano con un nuovo disco, «ADE (A Dance Eternal)». L'uscita interrompe un silenzio discografico durato sette anni ed è recensita dalla rivista musicale romana, che segnala il ritorno del gruppo come un evento per il circuito dark del nostro Paese. Il nuovo lavoro riporta così sotto i riflettori una band che ha segnato quell'ambiente musicale e che riprende ora il suo percorso creativo. Lo riferisce OndaRock.",
   "more": [
    "La darkwave è un filone nato tra la fine degli anni Settanta e gli anni Ottanta dall'incontro tra post-punk e new wave, con atmosfere cupe, sintetizzatori e voci malinconiche. In Italia ha conservato nel tempo una scena di nicchia ma molto fedele, con festival e etichette dedicate."
   ],
